-- Runner copy of server/src/db-draft/0005_district_identifier_authority.sql.
-- Generated by scripts/build-tenant-migration.mjs; edit the draft and regenerate, do not hand-edit
-- both. Differences from the draft: psql meta-commands removed, and BEGIN/COMMIT removed because
-- the migration runner applies every file inside its own transaction (and records the result in
-- schema_migrations). Semantics are otherwise identical.

-- =============================================================================
-- DHAROHAR — DRAFT migration 0005: make the district IDENTIFIER authoritative
--            (§4 phases 4-5 of docs/DISTRICT-TENANCY-MODEL.md)
--
-- WHY THIS FILE EXISTS — measured, not theorised. After 0004 added districts.id and
-- district_id on the four child tables, six rows in user_jurisdictions had district_id
-- NULL while their district_code resolved perfectly. They were written by the application
-- AFTER the backfill. Nothing in the write path produces an identifier: migration 0003's
-- trigger resolves the text to `district_code` and stops there. So the registry had a
-- stable key that new data simply did not use, and `district_id` could never be NOT NULL,
-- and no foreign key could be trusted to point at the identity rather than the name.
--
-- WHAT THIS DOES
--   1. Applies the owner's two decisions of 2026-10-19, both labelled as demo-environment
--      facts rather than certification: state_code='RJ' on the four canonical districts,
--      and every 'probe %' registry row retired (kind='retired', is_active=false). The
--      parcels under those fixtures stay exactly as they are — history preserved, no
--      organization relationship, and now refused for any NEW write.
--      The retirement is pattern-based and idempotent on purpose: the provisioning suite
--      has already created a twelfth probe district since 0004 ran, so a one-time list of
--      eleven would quietly rot.
--   2. Re-backfills district_id for rows the application created since, then ABORTS if any
--      child row still carries a district that cannot be resolved. It does not invent one.
--   3. Replaces the 0003 trigger with one that writes BOTH the code and the identifier on
--      every insert and update, so from here on the identifier is not optional.
--   4. Moves districts' primary key from the name-derived code to the surrogate id, and
--      repoints the four child foreign keys onto it. code keeps a UNIQUE constraint for
--      now: it is what makes text resolution single-valued, and dropping it is 0006's job
--      with state_code in the resolution path — not this file's.
--
-- WHAT IT DOES NOT DO
--   * It does not drop the global uniqueness of district codes, so two states cannot yet
--     hold a "Jaipur". That is the remaining step to multi-state geography, and it needs
--     the state of every registered district, not just four.
--   * It does not change user_jurisdictions' primary key. Two (user_id, district_id)
--     groups already have multiple rows (grant, revoke, grant again); a new primary key
--     would delete that history, which the owner's decision forbids.
--   * It does not touch row-level security. Policies come after the isolation tests in §7.
-- =============================================================================



-- ---- 1. The owner's two mappings, applied as demo-environment facts --------
DO $do$
DECLARE
  wanted   text[] := ARRAY['ajmer','jaipur','jodhpur','udaipur'];
  w         text;
  rows_hit  integer;
  applied   integer;
  n         integer := 0;
  skipped   text := '';
BEGIN
  -- Three outcomes per name, and only the last one is an error:
  --   exactly one canonical row -> apply the owner's mapping
  --   no canonical row          -> nothing to map. On a fresh installation the registry is empty,
  --                                and refusing to run there makes the file uninstallable; the
  --                                integrity gate's "apply every migration to a fresh database"
  --                                phase proved that by failing. A record that actually needed the
  --                                missing district is caught by 0004's unresolved-code abort, so
  --                                skipping labels nothing and loses nothing.
  --   more than one row         -> ambiguous. Which one carries the state is a decision, so abort.
  FOREACH w IN ARRAY wanted LOOP
    SELECT count(*) INTO rows_hit FROM districts d WHERE d.code = w AND d.kind = 'canonical';
    IF rows_hit = 1 THEN
      UPDATE districts
         SET state_code = 'RJ',
             country_code = 'IN',
             notes = btrim(coalesce(notes,'') || ' [0005] state code RJ supplied by the owner on 2026-10-19 for the synthetic demo environment only; it is not a certification of real land records.')
       WHERE code = w AND kind = 'canonical' AND state_code IS DISTINCT FROM 'RJ';
      GET DIAGNOSTICS applied = ROW_COUNT;
      n := n + applied;
    ELSIF rows_hit > 1 THEN
      RAISE EXCEPTION E'[STATE_MAPPING_AMBIGUOUS] district ''%'' has % canonical rows, so the owner''s mapping cannot be applied to one of them.\n  Reconcile the registry first. Nothing was changed.', w, rows_hit;
    ELSE
      skipped := skipped || ' ' || w;
    END IF;
  END LOOP;
  RAISE NOTICE '[0005] state_code applied to % canonical district(s); names with no row to map:%',
    n, nullif(btrim(skipped), '');

  -- Pattern-based, so the suite cannot quietly re-add geography-shaped rows between runs.
  UPDATE districts
     SET kind = 'retired',
         is_active = false,
         retired_at = coalesce(retired_at, now()),
         notes = btrim(coalesce(notes,'') || ' [0005] retired by owner decision 2026-10-19: test-suite fixture, not canonical geography. Its parcels remain as isolated synthetic fixtures and are refused for new writes.')
   WHERE code LIKE 'probe %' AND kind <> 'retired';
  GET DIAGNOSTICS n = ROW_COUNT;
  RAISE NOTICE '[0005] probe-pattern registry rows retired this run: %', n;
END
$do$;

-- ---- 2. Every registry row that exists gets the identifier it was written without --
--
-- Discovered on the live demo database, not in the drill: `probe 790279` was declared at
-- 2026-10-19T16:19:54Z, i.e. AFTER migration 0004 had already run. districts.id had no DEFAULT
-- until section 3 of this file, so the INSERT left it NULL, and a parcel written against it could
-- never be mapped. Any district declared between 0004 and this migration is in the same state.
--
-- Minting the identifier here is not a governance decision: it creates no district, re-homes no
-- record and asserts nothing about geography. It gives a row the registry already accepted the
-- stable key the model says every row must have. Refusing to do it would make the primary-key
-- move impossible on any database that has been written to since 0004.
DO $do$
DECLARE
  n integer;
BEGIN
  UPDATE districts SET id = gen_random_uuid() WHERE id IS NULL;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n > 0 THEN
    RAISE NOTICE '[0005] % registry row(s) had been written without an identifier (districts.id gained its DEFAULT only in this migration); minted one for each', n;
  END IF;
END
$do$;

-- ---- 3. Backfill the identifier for anything written since 0004, then stop --
DO $do$
DECLARE
  t        text;
  mapped   integer;
  stuck    text;
  stuckc   integer;
BEGIN
  FOREACH t IN ARRAY ARRAY['parcels','land_documents','users','user_jurisdictions'] LOOP
    EXECUTE format(
      'UPDATE %I c SET district_id = d.id
         FROM districts d
        WHERE c.district_code IS NOT NULL
          AND c.district_id IS NULL
          AND d.code = c.district_code', t);
    GET DIAGNOSTICS mapped = ROW_COUNT;
    IF mapped > 0 THEN
      RAISE NOTICE '[0005] %.district_id backfilled for % later-written row(s)', t, mapped;
    END IF;

    -- A row pointing at an inactive registry entry is allowed (that is what retiring means:
    -- the record keeps its history, the name stops being usable). A row pointing at nothing
    -- is the case that must never be guessed past.
    EXECUTE format(
      'SELECT string_agg(dc, %L ORDER BY dc) FROM (
         SELECT DISTINCT district_code AS dc FROM %I
          WHERE district_code IS NOT NULL AND district_id IS NULL LIMIT 25) s', ', ', t) INTO stuck;
    EXECUTE format(
      'SELECT count(*) FROM %I WHERE district_code IS NOT NULL AND district_id IS NULL', t) INTO stuckc;
    IF stuckc > 0 THEN
      RAISE EXCEPTION E'[DISTRICT_UNRESOLVED] % row(s) in % name a district (%) that no registry row answers. Nothing was changed.',
        stuckc, t, coalesce(stuck, '?');
    END IF;
  END LOOP;
END
$do$;

-- ---- 4. The identifier becomes non-optional on the write path --------------
-- Replaces migration 0003's function of the same name. Same contract for district_code,
-- plus: district_id is resolved in the same step, and an existing row is moved to a new
-- registry entry only through the re-homing path, which sets the text (and therefore gets
-- a matching id here).
CREATE OR REPLACE FUNCTION dharohar_sync_district_code() RETURNS trigger AS $fn$
DECLARE
  raw          TEXT := btrim(coalesce(NEW.district, ''));
  key          TEXT;
  found_id     UUID;
  active       BOOLEAN;
  -- Preserved from migration 0003 in meaning, not reinvented. On an UPDATE, NEW.district_code
  -- still carries the OLD value, so "a code was supplied" cannot mean "it is not null" — that
  -- reading turns every ordinary district change into a phantom conflict. Only a caller writing
  -- the key itself is being contradicted. district_id gets the same treatment.
  code_written BOOLEAN := (TG_OP = 'INSERT' AND NEW.district_code IS NOT NULL)
                          OR (TG_OP = 'UPDATE' AND NEW.district_code IS DISTINCT FROM OLD.district_code);
  id_written   BOOLEAN := (TG_OP = 'INSERT' AND NEW.district_id IS NOT NULL)
                          OR (TG_OP = 'UPDATE' AND NEW.district_id IS DISTINCT FROM OLD.district_id);
BEGIN
  IF TG_OP = 'UPDATE' AND raw = btrim(coalesce(OLD.district, ''))
     AND NOT code_written AND NOT id_written THEN
    -- The jurisdiction is not being changed. But a row written before this migration has no
    -- identifier at all, and without this fill it would stay NULL forever and district_id could
    -- never be trusted. Resolving it here is a repair of an existing fact, not a new claim: the
    -- code already on the row decides the answer, and an unanswerable code aborts rather than
    -- being given a plausible district.
    IF NEW.district_id IS NULL AND NEW.district_code IS NOT NULL THEN
      SELECT d.id INTO found_id FROM districts d WHERE d.code = NEW.district_code;
      IF found_id IS NULL THEN
        RAISE EXCEPTION 'DISTRICT_NOT_REGISTERED: % carries district_code % which no registry row answers',
          TG_TABLE_NAME, quote_literal(NEW.district_code)
          USING HINT = 'Register the district or move the record onto one that exists; this trigger will not '
                    || 'invent a jurisdiction to satisfy itself.';
      END IF;
      NEW.district_id := found_id;
    END IF;
    RETURN NEW;
  END IF;

  IF raw = '' THEN
    IF code_written OR id_written THEN
      RAISE EXCEPTION 'DISTRICT_CODE_CONFLICT: % carries district_code % but no district text to resolve it from',
        TG_TABLE_NAME, quote_literal(coalesce(NEW.district_code, NEW.district_id::text))
        USING HINT = 'Leave district_code and district_id NULL and let the trigger derive them from the district '
                  || 'text, or supply the text they stand for. A key with no jurisdiction behind it is an '
                  || 'authorization hole, not a shortcut.';
    END IF;
    NEW.district_code := NULL;             -- unresolved, not absent; the integrity checker reports it
    NEW.district_id   := NULL;
    RETURN NEW;
  END IF;

  key := lower(raw);
  SELECT d.id, d.is_active INTO found_id, active FROM districts d WHERE d.code = key;

  IF found_id IS NULL THEN
    RAISE EXCEPTION 'DISTRICT_NOT_REGISTERED: % matches no row in districts (looked up code %)',
      quote_literal(NEW.district), quote_literal(key)
      USING HINT = 'Register it first: INSERT INTO districts (code, name, provenance) VALUES ('
                || quote_literal(key) || ', ' || quote_literal(NEW.district) || ', ''declared''). '
                || 'This server will not invent a jurisdiction for a land record.';
  END IF;

  -- Same condition name as 0003 used for an inactive row, on purpose: jurisdiction.districtRefusal()
  -- maps DISTRICT_NOT_REGISTERED to a 400, and a new spelling would turn a clean rejection into a
  -- 503 that reads as an outage.
  IF NOT active THEN
    RAISE EXCEPTION 'DISTRICT_NOT_REGISTERED: % is registered but inactive, so nothing new may be filed under it',
      quote_literal(NEW.district)
      USING HINT = 'Re-activate districts where code = ' || quote_literal(key)
                || ', or file the record under an active district.';
  END IF;

  IF code_written OR (id_written AND NEW.district_id IS DISTINCT FROM found_id) THEN
    RAISE EXCEPTION 'DISTRICT_CODE_CONFLICT: % names district_code % / district_id % while its district text resolves to % / %',
      TG_TABLE_NAME, quote_literal(NEW.district_code), quote_literal(NEW.district_id),
      quote_literal(key), quote_literal(found_id)
      USING HINT = 'The caller must not pick a jurisdiction key that disagrees with the jurisdiction it writes. '
                || 'Either is right, both together is a record that two layers would read differently.';
  END IF;

  NEW.district_code := key;
  NEW.district_id   := found_id;
  RETURN NEW;
END
$fn$ LANGUAGE plpgsql;

-- Existing rows must satisfy the same rule the trigger now enforces, or the identifier
-- would be a claim about the future that the past contradicts.
DO $do$
DECLARE
  t       text;
  mismatch integer;
BEGIN
  FOREACH t IN ARRAY ARRAY['parcels','land_documents','users','user_jurisdictions'] LOOP
    EXECUTE format(
      'SELECT count(*) FROM %I c JOIN districts d ON d.id = c.district_id
        WHERE c.district_code IS DISTINCT FROM d.code', t) INTO mismatch;
    IF mismatch > 0 THEN
      RAISE EXCEPTION '[DISTRICT_ID_DRIFT] % row(s) in % have a district_id whose registry code is not their district_code. Nothing was changed.', mismatch, t;
    END IF;
  END LOOP;
END
$do$;

-- ---- 5. The primary key moves from the name to the identifier --------------
-- Order matters and is deliberate: the new key must exist before the old one goes, and the
-- child foreign keys that reference the OLD key must be gone before it can be dropped.
--
-- The names are migration 0003's explicit ones (fk_<table>_district_code), not PostgreSQL's
-- default <table>_district_code_fkey. The harness proved the difference: guessing the name made
-- DROP CONSTRAINT IF EXISTS a silent no-op, and the primary-key drop then failed with
-- "other objects depend on it" — a guard that quietly does nothing is worse than one that errors.
ALTER TABLE parcels            DROP CONSTRAINT IF EXISTS fk_parcels_district_code;
ALTER TABLE land_documents     DROP CONSTRAINT IF EXISTS fk_land_documents_district_code;
ALTER TABLE users              DROP CONSTRAINT IF EXISTS fk_users_district_code;
ALTER TABLE user_jurisdictions DROP CONSTRAINT IF EXISTS fk_user_jurisdictions_district_code;

-- 0004 declared district_id inline, so those foreign keys carry PostgreSQL's generated names.
-- Both name families are dropped before the new ones are added: without this, re-running the file
-- (which the runner refuses to do twice, but an operator re-applying after a partial drill will)
-- failed with "constraint already exists", which is what the idempotence assertion caught.
ALTER TABLE parcels            DROP CONSTRAINT IF EXISTS parcels_district_id_fkey;
ALTER TABLE land_documents     DROP CONSTRAINT IF EXISTS land_documents_district_id_fkey;
ALTER TABLE users              DROP CONSTRAINT IF EXISTS users_district_id_fkey;
ALTER TABLE user_jurisdictions DROP CONSTRAINT IF EXISTS user_jurisdictions_district_id_fkey;
ALTER TABLE parcels            DROP CONSTRAINT IF EXISTS fk_parcels_district_id;
ALTER TABLE land_documents     DROP CONSTRAINT IF EXISTS fk_land_documents_district_id;
ALTER TABLE users              DROP CONSTRAINT IF EXISTS fk_users_district_id;
ALTER TABLE user_jurisdictions DROP CONSTRAINT IF EXISTS fk_user_jurisdictions_district_id;

-- A primary key cannot be created on a nullable column, and 0004 left id nullable because it
-- backfilled rather than declared. But the default is the part that actually matters: existing
-- INSERT paths (districtRegistry.declareDistrict, provisioning's tenant rows) name their columns
-- and never mention id, so NOT NULL without a DEFAULT turns "declare a district" into a
-- not-null violation surfaced as PROVISIONING_FAILED. The suite that exercises exactly that path
-- caught it: 12 failures, of which the first caused the rest.
ALTER TABLE districts ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE districts ALTER COLUMN id SET NOT NULL;

-- Drop the OLD key only after the foreign keys that reference it are gone (above). Dropping
-- districts_pkey rather than "whatever the PK happens to be" is deliberate: the name is the one
-- migration 0002 created, and a rename would fail silently into "no PK exists".
ALTER TABLE districts DROP CONSTRAINT IF EXISTS districts_pkey;

DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'districts_id_pkey' AND conrelid = 'districts'::regclass) THEN
    ALTER TABLE districts ADD CONSTRAINT districts_id_pkey PRIMARY KEY (id);
  END IF;
END
$do$;

-- code stops being the primary key but stays unique: it is still what makes a text resolve to
-- exactly one row, and 0006 relaxes it once every district carries a state. Adding the unique
-- constraint BEFORE dropping the old primary key is what keeps that guarantee unbroken for the
-- instant in between.
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conname = 'ux_districts_code' AND conrelid = 'districts'::regclass) THEN
    ALTER TABLE districts ADD CONSTRAINT ux_districts_code UNIQUE (code);
  END IF;
END
$do$;

-- Children reference the identifier. NOT NULL is deliberately not asserted: existing rows
-- with no district at all (the two documents with neither district nor parcel, reported
-- since 0003) are legal, and inventing a district to satisfy a constraint is the thing this
-- project refuses to do.
ALTER TABLE parcels            ADD CONSTRAINT fk_parcels_district_id            FOREIGN KEY (district_id) REFERENCES districts(id);
ALTER TABLE land_documents     ADD CONSTRAINT fk_land_documents_district_id     FOREIGN KEY (district_id) REFERENCES districts(id);
ALTER TABLE users              ADD CONSTRAINT fk_users_district_id              FOREIGN KEY (district_id) REFERENCES districts(id);
ALTER TABLE user_jurisdictions ADD CONSTRAINT fk_user_jurisdictions_district_id FOREIGN KEY (district_id) REFERENCES districts(id);

-- ...and the code foreign keys come straight back. 0003 added them as the backstop for a bypassed
-- trigger (a restore, or session_replication_role=replica, which is exactly how the registry suite
-- plants its defects), and the first draft of this file dropped them to move the primary key —
-- which turned the code reference decorative and was caught as
-- "a district_code that is not in the registry ... the insert succeeded". A foreign key may
-- reference any UNIQUE column, and ux_districts_code above is what makes that legal now that the
-- primary key has moved. Both references are kept: the identifier is authoritative, the text key
-- is still impossible to violate quietly.
ALTER TABLE parcels            ADD CONSTRAINT fk_parcels_district_code            FOREIGN KEY (district_code) REFERENCES districts(code);
ALTER TABLE land_documents     ADD CONSTRAINT fk_land_documents_district_code     FOREIGN KEY (district_code) REFERENCES districts(code);
ALTER TABLE users              ADD CONSTRAINT fk_users_district_code              FOREIGN KEY (district_code) REFERENCES districts(code);
ALTER TABLE user_jurisdictions ADD CONSTRAINT fk_user_jurisdictions_district_code FOREIGN KEY (district_code) REFERENCES districts(code);

-- ---- 6. Report ----------------------------------------------------------------
DO $do$
DECLARE r RECORD;
BEGIN
  RAISE NOTICE '[0005] ===== post-state =====';
  RAISE NOTICE '[0005] districts=% canonical=% retired=% with_state=%',
    (SELECT count(*) FROM districts),
    (SELECT count(*) FROM districts WHERE kind='canonical'),
    (SELECT count(*) FROM districts WHERE kind='retired'),
    (SELECT count(*) FROM districts WHERE state_code IS NOT NULL);
  RAISE NOTICE '[0005] districts primary key = %',
    (SELECT string_agg(a.attname, ',') FROM pg_constraint c
       JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
      WHERE c.conrelid='districts'::regclass AND c.contype='p');
  FOR r IN SELECT tgname FROM pg_trigger WHERE tgname LIKE 'trg_%_district_code' ORDER BY 1 LOOP
    RAISE NOTICE '[0005] trigger % attached', r.tgname;
  END LOOP;
  FOR r IN
    SELECT 'parcels' AS t, count(*) AS rows_, count(district_id) AS with_id FROM parcels
    UNION ALL SELECT 'land_documents', count(*), count(district_id) FROM land_documents
    UNION ALL SELECT 'users', count(*), count(district_id) FROM users
    UNION ALL SELECT 'user_jurisdictions', count(*), count(district_id) FROM user_jurisdictions ORDER BY t
  LOOP
    RAISE NOTICE '[0005] %: rows=% district_id_set=%', r.t, r.rows_, r.with_id;
  END LOOP;
  RAISE NOTICE '[0005] ===== end =====';
END
$do$;


-- =============================================================================
-- STILL OUTSTANDING after this file (docs/DISTRICT-TENANCY-MODEL.md §8)
--   * code is still globally unique, so two states cannot both register "Jaipur". Needs a
--     state for every canonical district, then 0006 swaps UNIQUE(code) for
--     UNIQUE(name_key, state_code) and moves text resolution onto the pair.
--   * user_jurisdictions keeps (user_id, district) as its primary key because grant/revoke
--     history repeats that pair; a (user_id, district_id) key would delete rows.
--   * The provisioning suite still creates 'probe %' districts. Retiring them here is
--     idempotent, but the suite should stop minting registry rows at all.
--   * RLS is not enabled and no policy is written. See §7's test list.
-- =============================================================================
